const DB='mi-alquiler-db', STORE='records';let state={tenants:[],bills:[],owner:[],ownerRecurring:{mortgage:590.43,community:72.17,internet:6,startMonth:'2026-11'},garage:{name:'Arrendatario garaje',rent:60},settlements:[],outlookNotices:[]};
const MCP_INVOICE={"id": "mcp-AG2026555311", "type": "Mancomunidad", "amount": 128.83, "date": "2026-10-31", "settlementMonth": "2026-11", "periodStart": "2026-06-09", "periodEnd": "2026-12-31", "concept": "Mancomunidad · Factura AG2026555311 (recibida 02/11/2026)", "paid": false, "components": [{"type": "Agua", "amount": 67.68, "periodStart": "2026-06-09", "periodEnd": "2026-10-08"}, {"type": "Residuos", "amount": 61.15, "periodStart": "2026-09-01", "periodEnd": "2026-12-31"}], "doc": {"name": "AG202655531120261102093844S.pdf", "type": "application/pdf", "data": "data:application/pdf;base64,"}};
const $=id=>document.getElementById(id), euro=n=>Number(n||0).toLocaleString('es-ES',{style:'currency',currency:'EUR'}), today=()=>new Date().toISOString().slice(0,10), monthNow=()=>today().slice(0,7);
function dbOpen(){return new Promise((res,rej)=>{let r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(STORE);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function persist(){let db=await dbOpen();return new Promise((res,rej)=>{let tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(state,'main');tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
async function load(){try{let db=await dbOpen();state=await new Promise((res,rej)=>{let r=db.transaction(STORE).objectStore(STORE).get('main');r.onsuccess=()=>res(r.result||state);r.onerror=()=>rej(r.error)});}catch(e){console.error(e)}state.owner=state.owner||[];state.ownerRecurring=state.ownerRecurring||{mortgage:590.43,community:72.17,internet:6,startMonth:'2026-11'};state.ownerRecurring.mortgage=590.43;state.ownerRecurring.community=72.17;state.ownerRecurring.internet=6;state.ownerRecurring.startMonth='2026-11';if(!state.tenants.length){state.tenants=[{id:uid(),name:'Inquilino 1',rent:475,start:'2026-01-01',end:'',notes:''},{id:uid(),name:'Inquilino 2',rent:425,start:'2026-01-01',end:'',notes:''},{id:uid(),name:'Inquilino 3',rent:425,start:'2026-01-01',end:'',notes:''}]}let savedMcp=state.bills.find(b=>b.id==='mcp-AG2026555311');if(!savedMcp)state.bills.push(MCP_INVOICE);else{savedMcp.settlementMonth='2026-11';savedMcp.paid=false;savedMcp.components=MCP_INVOICE.components.map(c=>({...c}));savedMcp.periodStart=savedMcp.periodStart||MCP_INVOICE.periodStart;savedMcp.periodEnd=savedMcp.periodEnd||MCP_INVOICE.periodEnd;savedMcp.concept=savedMcp.concept||MCP_INVOICE.concept;savedMcp.amount=Number(savedMcp.amount)||MCP_INVOICE.amount;savedMcp.date=savedMcp.date||MCP_INVOICE.date;savedMcp.type=savedMcp.type||MCP_INVOICE.type;}await persist();$('monthPick').value='2026-11';$('settleMonth').value='2026-11';$('billDate').value=today();$('periodStart').value=monthNow()+'-01';$('periodEnd').value=today();$('ownerDate').value=today();render()}
function uid(){return crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random()}
function go(tab){document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id===tab));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));if(tab==='historial')renderHistory();window.scrollTo(0,0)}
$('nav').addEventListener('click',e=>{let b=e.target.closest('button[data-tab]');if(b)go(b.dataset.tab)});
function activeInMonth(t,m){let a=m+'-01',last=new Date(+m.slice(0,4),+m.slice(5),0).toISOString().slice(0,10);return (!t.start||t.start<=last)&&(!t.end||t.end>=a)}
function recurringOwnerTotal(m){let r=state.ownerRecurring||{mortgage:590.43,community:72.17,internet:6,startMonth:'2026-11'};return m>=r.startMonth?Number(r.mortgage||0)+Number(r.community||0)+Number(r.internet||0):0}
function ownerExpensesForMonth(m){let recurring=recurringOwnerTotal(m),extra=(state.owner||[]).filter(x=>(x.date||'').slice(0,7)===m).reduce((s,x)=>s+Number(x.amount||0),0);return {recurring,extra,total:recurring+extra}}
function render(){let m=$('monthPick').value||monthNow(),ts=state.tenants.filter(t=>activeInMonth(t,m)),home=ts.reduce((s,t)=>s+Number(t.rent||0),0),inc=home+Number(state.garage?.rent||0),bs=state.bills.filter(b=>!b.paid&&(b.components?b.settlementMonth===m:(b.periodStart||b.date||'').slice(0,7)<=m&&(b.periodEnd||b.date||'').slice(0,7)>=m)),oe=ownerExpensesForMonth(m);$('monthLabel').textContent=new Date(m+'-02').toLocaleDateString('es-ES',{month:'long',year:'numeric'});$('incomeTotal').textContent=euro(inc);$('incomeBottom').textContent=euro(inc);$('homeIncome').textContent=euro(home);$('garageIncome').textContent=euro(state.garage?.rent||0);$('ownerMetric').textContent=euro(oe.total);const monthlyBalance=Math.round((inc-oe.total)*100)/100;$('ownerBalance').textContent=euro(monthlyBalance);$('ownerBalance').classList.toggle('green',monthlyBalance>=0);$('ownerBalance').classList.toggle('red',monthlyBalance<0);$('balanceMetric').setAttribute('aria-label','Balance mensual: '+euro(monthlyBalance));$('billTotal').textContent=euro(bs.reduce((s,b)=>s+Number(b.amount),0));$('billCount').textContent=bs.length+' documentos';$('tenantCount').textContent=ts.length;let metricLabel=document.querySelector('#ownerMetric')?.parentElement;if(metricLabel){metricLabel.querySelector('small').textContent='Gastos totales del propietario';metricLabel.querySelectorAll('small')[1].textContent='Fijos + otros gastos del mes'}let oeSummary=$('ownerExpenseSummary');if(oeSummary){let r=state.ownerRecurring||{mortgage:590.43,community:72.17,internet:6,startMonth:'2026-11'};oeSummary.innerHTML=`<div class="card"><div class="row"><b>Gastos del propietario · ${esc(m)}</b><strong>${euro(oe.total)}</strong></div><div class="row"><span>Hipoteca</span><b>${euro(r.mortgage)}</b></div><div class="row"><span>Comunidad de propietarios</span><b>${euro(r.community)}</b></div><div class="row"><span>Internet</span><b>${euro(r.internet)}</b></div><div class="row"><span>Otros gastos del propietario este mes</span><b>${euro(oe.extra)}</b></div><small class="note">Los gastos fijos se suman automáticamente cada mes desde ${esc(r.startMonth)}. Estos gastos son tuyos y no se repercuten a los inquilinos.</small></div>`;}renderTenants();renderBills();renderOwnerMonthExtras(m);if($('garageName'))$('garageName').value=state.garage?.name||'';if($('garageRent'))$('garageRent').value=state.garage?.rent||0;renderHistory();renderOwnerRecurring()}
function renderOwnerRecurring(){let r=state.ownerRecurring||{mortgage:590.43,community:72.17,internet:6,startMonth:'2026-11'};let el=$('ownerRecurringSummary');if(el)el.innerHTML=`<div class="item"><b>Gastos fijos mensuales del propietario</b><p>Hipoteca: ${euro(r.mortgage)} · Comunidad: ${euro(r.community)} · Internet: ${euro(r.internet)}</p><div class="row"><span>Total mensual</span><strong>${euro(recurringOwnerTotal($('monthPick').value||'2026-11'))}</strong></div><small>Recurrentes desde ${r.startMonth}. Se contabilizan automáticamente en cada mes.</small></div>`}
function renderTenants(){$('tenantList').innerHTML=state.tenants.length?state.tenants.map(t=>`<div class="item"><div class="row"><h3>${esc(t.name)}</h3><span class="pill ${t.end?'warn':''}">${t.end?'Baja registrada':'Ficha activa'}</span></div><p>Renta: <b>${euro(t.rent)}</b> · Entrada: ${t.start||'—'} · Salida: ${t.end||'—'}</p><p>${esc(t.notes||'')}</p>${(t.absences||[]).length?'<p><b>Periodos fuera del piso:</b></p>'+t.absences.map((a,i)=>`<div class="row" style="gap:8px;align-items:center;margin:5px 0"><span>${a.start} a ${a.end}</span><button class="btn danger small" onclick="deleteAbsence('${t.id}',${i})">Eliminar</button></div>`).join(''):''}<div class="actions"><button class="btn secondary small" onclick="editTenant('${t.id}')">Editar</button><button class="btn secondary small" onclick="addAbsence('${t.id}')">Registrar ausencia</button><button class="btn secondary small" onclick="endTenant('${t.id}')">Registrar baja</button></div></div>`).join(''):'<div class="empty">Todavía no hay inquilinos.</div>'}
function saveTenant(){let id=$('tenantId').value,t={id:id||uid(),name:$('tenantName').value.trim(),rent:Number($('tenantRent').value),start:$('tenantStart').value,end:$('tenantEnd').value,notes:$('tenantNotes').value.trim()};if(!t.name||!Number.isFinite(t.rent)||t.rent<0||!t.start){alert('Introduce nombre, renta válida y fecha de entrada.');return}let i=state.tenants.findIndex(x=>x.id===id);if(i>=0){t.absences=state.tenants[i].absences||[];state.tenants[i]=t}else{t.absences=[];state.tenants.push(t)};persist().then(()=>{resetTenant();render()})}
function editTenant(id){let t=state.tenants.find(x=>x.id===id);$('tenantId').value=t.id;$('tenantName').value=t.name;$('tenantRent').value=t.rent;$('tenantStart').value=t.start;$('tenantEnd').value=t.end;$('tenantNotes').value=t.notes;$('tenantFormTitle').textContent='Editar inquilino';window.scrollTo(0,document.body.scrollHeight)}
function deleteAbsence(id,index){let t=state.tenants.find(x=>x.id===id);if(!t||!Array.isArray(t.absences)||!t.absences[index])return;let a=t.absences[index];if(!confirm('¿Eliminar el periodo de ausencia '+a.start+' a '+a.end+' de '+t.name+'? Esta acción no dará de baja al inquilino.'))return;t.absences.splice(index,1);persist().then(render)}
function addAbsence(id){let t=state.tenants.find(x=>x.id===id);if(!t)return;let a=prompt('Primer día que NO ocupa la vivienda (AAAA-MM-DD):',today());if(!a||!/^\d{4}-\d{2}-\d{2}$/.test(a))return;let z=prompt('Último día que NO ocupa la vivienda (AAAA-MM-DD):',a);if(!z||!/^\d{4}-\d{2}-\d{2}$/.test(z)||z<a){alert('Fechas no válidas.');return}t.absences=t.absences||[];t.absences.push({start:a,end:z});persist().then(render)}
function endTenant(id){let t=state.tenants.find(x=>x.id===id),d=prompt('Fecha de salida (AAAA-MM-DD). El día de salida cuenta como ocupado:',today());if(d&&/^\\d{4}-\\d{2}-\\d{2}$/.test(d)){t.end=d;persist().then(render)}}
function resetTenant(){['tenantId','tenantName','tenantRent','tenantStart','tenantEnd','tenantNotes'].forEach(x=>$(x).value='');$('tenantFormTitle').textContent='Añadir inquilino'}
function saveGarage(){state.garage={name:$('garageName').value.trim(),rent:Number($('garageRent').value)||0};persist().then(render);alert('Datos del garaje guardados.')}
function toggleMcpFields(){let on=$('billType').value==='Mancomunidad';$('mcpFields').style.display=on?'block':'none'}
function saveBill(){let type=$('billType').value,amount=Number($('billAmount').value),file=$('billFile').files[0];if(!(amount>=0)||!$('billDate').value){alert('Indica importe y fecha.');return}let components=null;if(type==='Mancomunidad'){let wa=Number($('mcpWaterAmount').value),ra=Number($('mcpWasteAmount').value),ws=$('mcpWaterStart').value,we=$('mcpWaterEnd').value,rs=$('mcpWasteStart').value,re=$('mcpWasteEnd').value;if(!(wa>=0&&ra>=0)||!ws||!we||!rs||!re||we<ws||re<rs){alert('Completa importes y periodos válidos de agua y residuos.');return}if(Math.round((wa+ra)*100)!==Math.round(amount*100)){alert('La suma de agua y residuos debe coincidir con el importe total de la factura.');return}components=[{type:'Agua',amount:wa,periodStart:ws,periodEnd:we},{type:'Residuos',amount:ra,periodStart:rs,periodEnd:re}]}let add=async()=>{let doc=null;if(file)doc={name:file.name,type:file.type,data:await fileToData(file)};state.bills.push({id:uid(),type,amount,date:$('billDate').value,settlementMonth:components?$('billDate').value.slice(0,7):undefined,periodStart:components?components.map(c=>c.periodStart).sort()[0]:$('periodStart').value,periodEnd:components?components.map(c=>c.periodEnd).sort().slice(-1)[0]:$('periodEnd').value,concept:$('billConcept').value,doc,components});await persist();$('billAmount').value='';$('billConcept').value='';$('billFile').value='';['mcpWaterAmount','mcpWasteAmount','mcpWaterStart','mcpWaterEnd','mcpWasteStart','mcpWasteEnd'].forEach(id=>$(id).value='');render()};add()}
function fileToData(f){return new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)})}
function renderBills(){renderOutlookNotices();$('billList').innerHTML='<h3>Facturas repercutibles</h3>'+(state.bills.length?state.bills.map(b=>`<div class="item"><div class="row"><b>${esc(b.type)}</b><b>${euro(b.amount)}</b></div><p>${esc(b.concept||'')} · Fecha ${b.date}</p><p>Periodo: ${b.periodStart||'—'} a ${b.periodEnd||'—'}</p>${b.components?b.components.map(c=>`<p><b>${esc(c.type)}:</b> ${euro(c.amount)} · ${c.periodStart} a ${c.periodEnd}</p>`).join(''):''}<p><span class="pill ${b.paid?'':'warn'}">${b.paid?'Ya pagada · no se reparte':'Pendiente / por liquidar'}</span></p>${b.doc?`<p>Adjunto: ${esc(b.doc.name)} <button class="btn secondary small" onclick="downloadDoc('${b.id}')">Abrir/descargar</button></p>`:(b.pdfPending?'<p><span class="pill warn">PDF original pendiente de adjuntar</span></p>':'<p>Sin documento adjunto</p>')}<label class="btn secondary small" style="display:inline-block">Adjuntar PDF<input type="file" accept=".pdf,image/*" style="display:none" onchange="attachBillDoc('${b.id}',this)"></label> <button class="btn secondary small" onclick="toggleBillPaid('${b.id}')">${b.paid?'Reabrir factura':'Marcar pagada'}</button> <button class="btn danger small" onclick="deleteBill('${b.id}')">Eliminar</button></div>`).join(''):'<div class="empty">No hay facturas registradas.</div>');$('ownerList').innerHTML='<h3>Gastos del propietario</h3>'+(state.owner.length?state.owner.map((b,i)=>`<div class="item"><div class="row"><b>${esc(b.type)}</b><b>${euro(b.amount)}</b></div><p>${b.date} · ${esc(b.concept)}</p><button class="btn danger small" onclick="deleteOwner(${i})">Eliminar</button></div>`).join(''):'<div class="empty">No hay gastos registrados.</div>')}

function parseDateAny(s){if(!s)return '';let m=s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/);if(m)return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;return s}
function openChatGPTInvoiceCheck(){const prompt=`Consulta mi Outlook mediante la conexión de correo disponible en ChatGPT. Busca mensajes recientes relacionados con facturas de mi alquiler en Pamplona, especialmente de BASER / BASER COR y de la Mancomunidad de la Comarca de Pamplona.\n\nPara cada factura o aviso encontrado: indica proveedor, asunto, remitente, fecha de recepción, número de factura si aparece, tipo de suministro o concepto, importe total, fecha de emisión, periodo facturado y fecha límite de pago si consta. Prioriza los mensajes recientes y evita incluir avisos que claramente indiquen que ya están pagados o anulados. No inventes datos que no figuren en el correo.\n\nDespués, copia o resume el contenido relevante del correo original de cada factura, conservando importes, fechas y periodos exactamente como aparecen, para que pueda pegarlo en el apartado de revisión manual de Mi Alquiler. Si no puedes acceder a Outlook o no encuentras mensajes, indícalo claramente. No afirmes que has registrado nada en Mi Alquiler: la incorporación la haré yo después de revisar los datos.`;const w=window.open('https://chatgpt.com/','_blank');const status=$('chatgptPromptStatus');if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(prompt).then(()=>{if(status)status.textContent='Instrucción copiada. En la pestaña de ChatGPT, pégala en el cuadro de mensaje y envíala.';}).catch(()=>{if(status)status.innerHTML='No se pudo copiar automáticamente. <textarea id="chatgptPromptFallback" style="width:100%;min-height:180px;margin-top:8px"></textarea><button class="btn secondary small" onclick="copyChatGPTPromptFallback()">Copiar instrucción</button>';const ta=$('chatgptPromptFallback');if(ta)ta.value=prompt;});}else{if(status)status.innerHTML='Copia esta instrucción y pégala en ChatGPT:<textarea id="chatgptPromptFallback" style="width:100%;min-height:180px;margin-top:8px"></textarea><button class="btn secondary small" onclick="copyChatGPTPromptFallback()">Copiar instrucción</button>';const ta=$('chatgptPromptFallback');if(ta)ta.value=prompt;}if(!w&&status)status.textContent+=' Si no se abrió ChatGPT, ábrelo manualmente en otra pestaña.';}
function copyChatGPTPromptFallback(){const ta=$('chatgptPromptFallback');if(!ta)return;ta.focus();ta.select();try{document.execCommand('copy');alert('Instrucción copiada. Pégala en ChatGPT y envíala.')}catch(e){alert('Selecciona y copia el texto manualmente.')}}
function importOutlookNotice(){let raw=$('outlookMailText').value.trim().replace(/\*\*/g,'').replace(/<[^>]*>/g,' ');if(!raw){alert('Pega primero el contenido del correo de Baser.');return}let low=raw.toLowerCase();let type=/\b(gas)\b/.test(low)?'Gas':(/\b(luz|electricidad)\b/.test(low)?'Electricidad':'');let am=raw.match(/(?:Importe\s*:\s*)?(\d{1,4}[.,]\d{2})\s*€/i);let dm=raw.match(/Fecha de emisi[oó]n\s*:\s*(\d{1,2}[./-]\d{1,2}[./-]\d{4})/i)||raw.match(/(\d{1,2}[./-]\d{1,2}[./-]\d{4})\s*\|\s*(?:Luz|Gas)/i);let pm=raw.match(/(?:Periodo de consumo|Periodo)\s*:\s*Del\s*(\d{1,2}[./-]\d{1,2}[./-]\d{4})\s*al\s*(\d{1,2}[./-]\d{1,2}[./-]\d{4})/i);if(!type||!am||!dm){$('outlookPreview').innerHTML='<p class="note" style="color:#a63b35">No he podido identificar con seguridad tipo, importe y fecha. Comprueba que has pegado el aviso completo.</p>';return}let amount=Number(am[1].replace(',','.')),date=parseDateAny(dm[1]),periodStart=pm?parseDateAny(pm[1]):'',periodEnd=pm?parseDateAny(pm[2]):'';let key=[type,amount.toFixed(2),date,periodStart,periodEnd].join('|');let duplicate=state.bills.some(b=>b.sourceKey===key)||state.outlookNotices.some(n=>n.key===key);if(duplicate){$('outlookPreview').innerHTML='<p class="pill warn">Este aviso ya consta en la aplicación; no se ha duplicado.</p>';return}let notice={id:uid(),key,type,amount,date,periodStart,periodEnd,status:'Pendiente de PDF',paid:false,created:new Date().toISOString()};state.outlookNotices.push(notice);persist().then(()=>{ $('outlookPreview').innerHTML=`<div class="item"><b>Aviso identificado</b><p>${type} · ${euro(amount)} · Emisión ${date}</p><p>Periodo: ${periodStart||'No indicado'} a ${periodEnd||'No indicado'}</p><span class="pill warn">Pendiente de PDF original</span></div>`;renderOutlookNotices()})}
function renderOutlookNotices(){let el=$('outlookNoticeList');if(!el)return;el.innerHTML='<h3>Avisos detectados</h3>'+(state.outlookNotices?.length?state.outlookNotices.slice().reverse().map(n=>`<div class="item"><div class="row"><b>${esc(n.type)} · ${euro(n.amount)}</b><span class="pill ${n.status==='PDF incorporado'?'':'warn'}">${esc(n.status)}</span></div><p>Emisión: ${n.date} · Periodo: ${n.periodStart||'—'} a ${n.periodEnd||'—'}</p><div class="actions"><button class="btn secondary small" onclick="useNotice('${n.id}')">Pasar a factura</button><button class="btn secondary small" onclick="markNoticePaid('${n.id}')">Marcar ya pagada</button><button class="btn danger small" onclick="removeNotice('${n.id}')">Quitar aviso</button></div></div>`).join(''):'<div class="empty">Todavía no has importado avisos de Outlook.</div>')}
function markNoticePaid(id){let n=state.outlookNotices.find(x=>x.id===id);if(n){n.paid=true;n.status='Ya pagada · histórica';persist().then(renderOutlookNotices)}}
function useNotice(id){let n=state.outlookNotices.find(x=>x.id===id);if(!n)return;if(n.paid){alert('Este aviso está marcado como pagado y no se incorporará a una liquidación.');return}let key=n.key;if(state.bills.some(b=>b.sourceKey===key)){alert('La factura ya está registrada.');return}let bill={id:uid(),type:n.type,amount:n.amount,date:n.date,periodStart:n.periodStart,periodEnd:n.periodEnd,concept:'Baser · importado desde aviso de Outlook',doc:null,sourceKey:key,pdfPending:true};state.bills.push(bill);n.status='Factura registrada · PDF pendiente';persist().then(render);go('facturas');alert('Datos incorporados. Adjunta el PDF original en la ficha de la factura cuando lo descargues.')}
function removeNotice(id){if(confirm('¿Quitar este aviso de la lista?')){state.outlookNotices=state.outlookNotices.filter(n=>n.id!==id);persist().then(renderOutlookNotices)}}

async function attachBillDoc(id,input){let f=input.files?.[0];if(!f)return;let b=state.bills.find(x=>x.id===id);if(!b)return;b.doc={name:f.name,type:f.type,data:await fileToData(f)};b.pdfPending=false;let n=state.outlookNotices?.find(x=>x.key===b.sourceKey);if(n)n.status='PDF incorporado';await persist();render();alert('Documento original adjuntado correctamente.')}
function toggleBillPaid(id){let b=state.bills.find(x=>x.id===id);if(b){b.paid=!b.paid;persist().then(render)}}
function deleteBill(id){if(confirm('¿Eliminar esta factura y su adjunto?')){state.bills=state.bills.filter(x=>x.id!==id);persist().then(render)}}
function downloadDoc(id){let b=state.bills.find(x=>x.id===id);if(!b?.doc)return;let a=document.createElement('a');a.href=b.doc.data;a.download=b.doc.name;a.click()}
function saveOwnerExpense(){let amount=Number($('ownerAmount').value);if(!(amount>0)||!$('ownerDate').value){alert('Indica un importe superior a cero y la fecha del gasto.');return}state.owner.push({type:$('ownerType').value,amount,date:$('ownerDate').value,concept:$('ownerConcept').value});persist().then(()=>{ $('ownerAmount').value='';$('ownerConcept').value='';render()})}
function renderOwnerMonthExtras(m){let el=$('ownerMonthExtras');if(!el)return;let items=(state.owner||[]).map((x,i)=>({...x,_i:i})).filter(x=>(x.date||'').slice(0,7)===m);let total=items.reduce((a,x)=>a+Number(x.amount||0),0);el.innerHTML=`<div style="border-top:1px solid var(--line);margin-top:14px;padding-top:12px"><div class="row"><b>Gastos puntuales de ${esc(m)}</b><b>${euro(total)}</b></div>${items.length?items.map(x=>`<div class="item"><div class="row"><b>${esc(x.type||'Otro')}</b><b>${euro(x.amount)}</b></div><p>${esc(x.date||'')} · ${esc(x.concept||'Sin detalle')}</p><button class="btn danger small" onclick="deleteOwner(${x._i})">Eliminar gasto</button></div>`).join(''):'<p class="note">No hay gastos puntuales registrados para este mes.</p>'}</div>`} 
function deleteOwner(i){if(!confirm('¿Eliminar este gasto puntual del propietario?'))return;state.owner.splice(i,1);persist().then(render)}
function daysBetween(a,b){let d=[];for(let x=new Date(a+'T12:00:00');x<=new Date(b+'T12:00:00');x.setDate(x.getDate()+1))d.push(x.toISOString().slice(0,10));return d}
function isContractTenantOnDay(t,d){return !(t.start&&t.start>d)&&!(t.end&&t.end<d)}
function isOccupantOnDay(t,d){return isContractTenantOnDay(t,d)&&!(t.absences||[]).some(a=>a.start<=d&&a.end>=d)}
function calculateSettlement(){let m=$('settleMonth').value;if(!m)return;let start=m+'-01',end=new Date(+m.slice(0,4),+m.slice(5),0).toISOString().slice(0,10),days=Number(end.slice(-2));let tenants=state.tenants.filter(t=>activeInMonth(t,m));let costs={};function ensure(t){if(!costs[t.id])costs[t.id]={tenant:t,amount:0,days:0,water:0,waste:0,electricity:0,other:0,details:[]};return costs[t.id]}tenants.forEach(t=>ensure(t));
let bills=state.bills.filter(b=>{if(b.id==='mcp-AG2026555311')return m==='2026-11';if(b.paid)return false;if(b.components)return b.settlementMonth===m;return (b.periodStart||b.date||'').slice(0,10)<=end&&(b.periodEnd||b.date||'').slice(0,10)>=start});
for(let b of bills){if(b.components){for(let c of b.components){let period=daysBetween(c.periodStart,c.periodEnd),n=period.length||1;for(let d of period){let isMariuska=t=>String(t.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()==='mariuska';let eligible=state.tenants.filter(t=>isMariuska(t)?(!t.start||t.start<=d):(c.type==='Residuos'?isContractTenantOnDay(t,d):isOccupantOnDay(t,d)));if(!eligible.length)continue;let share=Number(c.amount)/n/eligible.length;eligible.forEach(t=>{let x=ensure(t);x.amount+=share;if(c.type==='Agua')x.water+=share;else if(c.type==='Residuos')x.waste+=share;x.details.push(c.type)})}}}else{let ps=b.periodStart||b.date,pe=b.periodEnd||b.date,period=daysBetween(ps,pe),n=period.length||1;for(let d of period){if(d<start||d>end)continue;let occ=state.tenants.filter(t=>isOccupantOnDay(t,d));if(!occ.length)continue;let share=Number(b.amount)/n/occ.length;occ.forEach(t=>{let x=ensure(t);x.amount+=share;if(String(b.type||'').toLowerCase()==='electricidad')x.electricity+=share;else x.other+=share;x.details.push(b.type)})}}}
for(let t of tenants){let a=t.start&&t.start>start?t.start:start,z=t.end&&t.end<end?t.end:end;if(a<=z){let occupied=daysBetween(a,z).filter(d=>isOccupantOnDay(t,d));let x=ensure(t);x.days=occupied.length;let internet=5*occupied.length/days;x.amount+=internet;x.other+=internet}}
let rows=Object.values(costs).filter(x=>x.amount>0||tenants.some(t=>t.id===x.tenant.id)).map(x=>({id:x.tenant.id,name:x.tenant.name,amount:+x.amount.toFixed(2),days:x.days,water:+x.water.toFixed(2),waste:+x.waste.toFixed(2),electricity:+x.electricity.toFixed(2),other:+x.other.toFixed(2),details:[...new Set(x.details)]}));let sum=rows.reduce((s,x)=>s+x.amount,0);let result={month:m,rows,total:+sum.toFixed(2),created:new Date().toISOString()};state.settlements=state.settlements.filter(x=>x.month!==m);state.settlements.push(result);persist();let totalWater=result.rows.reduce((s,r)=>s+r.water,0),totalWaste=result.rows.reduce((s,r)=>s+r.waste,0),totalElectricity=result.rows.reduce((s,r)=>s+(r.electricity||0),0),totalOther=result.rows.reduce((s,r)=>s+r.other,0);$('settlementResult').innerHTML=`<div class="card"><div class="row"><b>Resultado · ${m}</b><span class="pill">Cálculo</span></div><p class="note">Agua: reparto diario entre quienes ocupaban efectivamente la vivienda (las ausencias temporales no pagan agua). Residuos de Mancomunidad: reparto diario entre titulares de contrato vigente, aunque estén temporalmente ausentes. La electricidad se muestra por separado; los demás conceptos aparecen en «Otros». Las bajas definitivas dejan de participar desde su fecha efectiva.</p><div class="table-wrap"><table class="table"><tr><th>Inquilino</th><th>Agua</th><th>Mancomunidad (residuos)</th><th>Luz</th><th>Otros</th><th>Total</th></tr>${result.rows.map(r=>`<tr><td>${esc(r.name)}<br><small>${r.days} días ocupados en ${m}</small></td><td>${euro(r.water)}</td><td>${euro(r.waste)}</td><td>${euro(r.electricity||0)}</td><td>${euro(r.other)}</td><td><b>${euro(r.amount)}</b></td></tr>`).join('')}<tr style="font-weight:700;border-top:2px solid var(--line)"><td>TOTALES</td><td>${euro(totalWater)}</td><td>${euro(totalWaste)}</td><td>${euro(totalElectricity)}</td><td>${euro(totalOther)}</td><td>${euro(result.total)}</td></tr></table><div class="row" style="margin-top:12px"><b>Total a repartir</b><strong class="total">${euro(result.total)}</strong></div><p class="note">El alquiler y la cuota de residuos se mantienen durante una ausencia temporal. Agua e internet se calculan solo por días de ocupación efectiva. Una baja definitiva excluye al inquilino desde la fecha de salida. Las facturas marcadas como pagadas quedan excluidas.</p></div>`;renderHistory()}
function printSettlement(){if(!$('settlementResult').querySelector('.card')){alert('Calcula primero la liquidación.');return}let w=window.open('','_blank');if(!w){alert('Permite las ventanas emergentes para generar el PDF.');return}w.document.write('<html><head><title>Liquidación Mi Alquiler</title><style>body{font:14px Arial;padding:30px}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #ccc;text-align:left}</style></head><body><h1>Liquidación de gastos</h1>'+ $('settlementResult').innerHTML+'</body></html>');w.document.close();w.print()}
function renderHistory(){$('historyList').innerHTML=state.settlements.length?state.settlements.slice().reverse().map(s=>`<div class="item"><div class="row"><b>${s.month}</b><b>${euro(s.total)}</b></div>${s.rows.map(r=>`<div class="row"><span>${esc(r.name)}</span><span>${euro(r.amount)}</span></div><div class="row"><span class="muted">Estado del pago</span><select style="max-width:180px" onchange="setPay('${s.month}','${r.id}',this.value)"><option ${r.pay==='Pendiente'?'selected':''}>Pendiente</option><option ${r.pay==='Pagado'?'selected':''}>Pagado</option><option ${r.pay==='Parcial'?'selected':''}>Parcial</option><option ${r.pay==='Pendiente de comprobar'?'selected':''}>Pendiente de comprobar</option></select></div>`).join('')}</div>`).join(''):'<div class="empty">Todavía no hay liquidaciones guardadas.</div>'}
function setPay(m,id,v){let s=state.settlements.find(x=>x.month===m),r=s?.rows.find(x=>x.id===id);if(r){r.pay=v;persist()}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$('monthPick').addEventListener('change',render);
async function exportBackup(){try{const backup={format:'MiAlquilerBackup',version:1,exported:new Date().toISOString(),state};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Mi-Alquiler-copia-'+today()+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);alert('Copia de seguridad preparada. Comprueba que el archivo Mi-Alquiler-copia-'+today()+'.json aparece en la carpeta Descargas.');}catch(e){alert('No se pudo crear la copia: '+e.message)}}
async function restoreBackup(){const input=$('restoreFile'),f=input.files[0];if(!f){alert('Selecciona primero un archivo de copia JSON.');return}if(!confirm('ATENCIÓN: la restauración sustituirá todos los datos actuales de Mi Alquiler. Es recomendable descargar antes una copia de seguridad actual. ¿Quieres continuar?'))return;try{const x=JSON.parse(await f.text());if(x.format!=='MiAlquilerBackup'||!x.state||!Array.isArray(x.state.tenants)||!Array.isArray(x.state.bills)||!Array.isArray(x.state.settlements))throw Error('El archivo no tiene el formato de una copia válida de Mi Alquiler.');const restored=x.state;restored.owner=Array.isArray(restored.owner)?restored.owner:[];restored.outlookNotices=Array.isArray(restored.outlookNotices)?restored.outlookNotices:[];restored.ownerRecurring=restored.ownerRecurring||{mortgage:590.43,community:72.17,internet:6,startMonth:'2026-11'};restored.ownerRecurring.mortgage=590.43;restored.ownerRecurring.community=72.17;restored.ownerRecurring.internet=6;restored.ownerRecurring.startMonth='2026-11';state=restored;await persist();render();input.value='';alert('Copia restaurada correctamente. Tus datos y documentos vuelven a estar disponibles en esta aplicación.');}catch(e){alert('No se pudo restaurar la copia: '+e.message)}}
load();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(console.warn));
